/** Registry admin pusat, terpisah dari 58 aplikasi CBT sekolah. */
function setupCentralRegistry() {
  const props = PropertiesService.getScriptProperties();
  const currentId = props.getProperty('CENTRAL_SPREADSHEET_ID');
  const ss = currentId ? SpreadsheetApp.openById(currentId)
    : SpreadsheetApp.create('CBT 58 Sekolah - Admin Pusat');
  if (!currentId) props.setProperty('CENTRAL_SPREADSHEET_ID', ss.getId());
  const sheet = ss.getSheetByName('Inventaris Sekolah') || ss.getActiveSheet();
  sheet.setName('Inventaris Sekolah');
  if (sheet.getLastRow() < 2) {
    const rows = getCentralSeed_();
    sheet.getRange(1,1,1,10).setValues([[
      'SCHOOL_ID','NAMA_SEKOLAH','ACCOUNT_ID','EMAIL_PEMILIK','FIREBASE_GRUP',
      'WARNA','LINK_SPREADSHEET','LINK_WEBAPP','LINK_FOLDER_DRIVE','STATUS'
    ]]);
    sheet.getRange(2,1,rows.length,10).setValues(rows);
    sheet.setFrozenRows(1);
    sheet.getRange(1,1,1,10).setFontWeight('bold').setBackground('#1E293B').setFontColor('#FFFFFF');
    sheet.getRange(1,1,rows.length+1,10).createFilter();
    for (var i = 0; i < rows.length; i++) {
      sheet.getRange(i+2,6).setBackground(rows[i][5]).setFontColor('#FFFFFF');
    }
  }
  Logger.log('LINK_ADMIN_PUSAT=' + ss.getUrl());
  return ss.getUrl();
}

function getCentralSeed_() {
  return SEED_58_SEKOLAH;
}
